package com.smartparking.ui;

import com.smartparking.exception.*;
import com.smartparking.model.*;
import com.smartparking.service.ParkingManager;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Duration;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/** One main window with small card panels, keeping navigation and shared data straightforward. */
public final class DashboardFrame extends JFrame {
    private final ParkingManager manager;
    private final ParkingAttendant attendant;
    private final ExecutorService fileWorker=Executors.newSingleThreadExecutor(r->new Thread(r,"parking-file-worker"));
    private final CardLayout cards=new CardLayout(); private final JPanel content=new JPanel(cards);
    private final JLabel status=new JLabel("Loading saved parking data…"), clock=new JLabel();
    private boolean dataReady;
    private final JPanel slotsPanel=new JPanel(new GridLayout(0,5,10,10));
    private final JLabel[] stats=new JLabel[4];
    private final JTextField registration=new JTextField(),owner=new JTextField(), lookup=new JTextField(),historySearch=new JTextField();
    private final JComboBox<VehicleType> vehicleType=new JComboBox<>(VehicleType.values()), historyType=new JComboBox<>(new Object[]{"All types",VehicleType.CAR,VehicleType.BIKE});
    private final JLabel exitSummary=new JLabel("Search by vehicle registration or ticket ID to view the bill.");
    private ParkingRecord pendingExit;
    private final DefaultTableModel tableModel=new DefaultTableModel(new String[]{"Ticket","Vehicle","Type","Slot","Entry","Exit","Duration","Paid"},0){public boolean isCellEditable(int r,int c){return false;}};
    private final JTable historyTable=new JTable(tableModel);
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd MMM yyyy, HH:mm");
    public DashboardFrame(ParkingManager manager,ParkingAttendant attendant){
        this.manager=manager;this.attendant=attendant;setTitle("Smart Parking Management System");setDefaultCloseOperation(EXIT_ON_CLOSE);setMinimumSize(new Dimension(1050,720));setSize(1200,800);setLocationRelativeTo(null);
        JPanel shell=new JPanel(new BorderLayout());shell.add(sidebar(),BorderLayout.WEST);content.setBackground(UiStyle.BG);content.add(homePage(),"Dashboard");content.add(entryPage(),"Entry");content.add(exitPage(),"Exit");content.add(historyPage(),"History");shell.add(content,BorderLayout.CENTER);setContentPane(shell);
        Timer timer=new Timer(1000,e->clock.setText(LocalDateTime.now().format(DateTimeFormatter.ofPattern("EEEE, dd MMM yyyy   •   HH:mm:ss"))));timer.start();
        setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
        addWindowListener(new java.awt.event.WindowAdapter(){@Override public void windowClosing(java.awt.event.WindowEvent e){setEnabled(false);fileWorker.submit(()->{try{manager.save();}catch(Exception ex){System.err.println("Could not save while closing: "+ex.getMessage());}SwingUtilities.invokeLater(()->System.exit(0));});fileWorker.shutdown();}});
        SwingWorker<Void,Void> loader=new SwingWorker<>(){protected Void doInBackground()throws Exception{manager.load();return null;}protected void done(){try{get();dataReady=true;status.setText("Parking data is ready");refreshAll();}catch(Exception ex){status.setText("Could not load saved data");JOptionPane.showMessageDialog(DashboardFrame.this,"Saved data could not be loaded: "+ex.getMessage(),"Storage error",JOptionPane.ERROR_MESSAGE);}}};loader.execute();
    }
    private JPanel sidebar(){JPanel side=new JPanel();side.setBackground(UiStyle.NAVY);side.setPreferredSize(new Dimension(230,0));side.setLayout(new BoxLayout(side,BoxLayout.Y_AXIS));side.setBorder(new EmptyBorder(25,16,20,16));JLabel brand=new JLabel("  P  Smart Parking");brand.setForeground(Color.WHITE);brand.setFont(new Font("Segoe UI",Font.BOLD,18));brand.setBorder(new EmptyBorder(4,0,34,0));side.add(brand);
        JLabel signedIn=new JLabel("  Signed in: "+attendant.getUsername());signedIn.setForeground(new Color(178,190,209));signedIn.setFont(new Font("Segoe UI",Font.PLAIN,12));signedIn.setBorder(new EmptyBorder(0,0,14,0));side.add(signedIn);nav(side,"Dashboard","Dashboard");nav(side,"Vehicle Entry","Entry");nav(side,"Vehicle Exit","Exit");nav(side,"Parking History","History");side.add(Box.createVerticalGlue());JButton logout=new JButton("Logout");styleNav(logout);logout.addActionListener(e->{logout.setEnabled(false);fileWorker.submit(()->{try{manager.save();}catch(Exception ex){System.err.println("Could not save while logging out: "+ex.getMessage());}SwingUtilities.invokeLater(()->{new LoginFrame(new com.smartparking.util.CsvFileStore(java.nio.file.Path.of("data"))).setVisible(true);dispose();});});fileWorker.shutdown();});side.add(logout);return side;}
    private void nav(JPanel side,String label,String page){JButton b=new JButton(label);styleNav(b);b.addActionListener(e->{cards.show(content,page);if(page.equals("History"))refreshHistory();});side.add(b);side.add(Box.createVerticalStrut(8));}
    private void styleNav(JButton b){b.setAlignmentX(Component.LEFT_ALIGNMENT);b.setHorizontalAlignment(SwingConstants.LEFT);b.setForeground(new Color(230,235,244));b.setBackground(UiStyle.NAVY);b.setBorder(new EmptyBorder(12,13,12,8));b.setFont(UiStyle.REGULAR);b.setFocusPainted(false);b.setMaximumSize(new Dimension(205,45));}
    private JPanel basePage(String title,String subtitle){JPanel p=new JPanel(new BorderLayout(0,20));p.setBackground(UiStyle.BG);p.setBorder(new EmptyBorder(28,32,28,32));JPanel head=new JPanel(new BorderLayout());head.setOpaque(false);JPanel titles=new JPanel(new GridLayout(2,1,0,4));titles.setOpaque(false);JLabel t=new JLabel(title);t.setFont(UiStyle.TITLE);t.setForeground(UiStyle.TEXT);JLabel s=new JLabel(subtitle);s.setForeground(UiStyle.MUTED);titles.add(t);titles.add(s);head.add(titles,BorderLayout.WEST);clock.setForeground(UiStyle.MUTED);head.add(clock,BorderLayout.EAST);p.add(head,BorderLayout.NORTH);return p;}
    private JPanel homePage(){JPanel p=basePage("Parking dashboard","Live overview of the parking area");JPanel body=new JPanel(new BorderLayout(0,18));body.setOpaque(false);JPanel statsPanel=new JPanel(new GridLayout(1,4,12,0));statsPanel.setOpaque(false);String[] labels={"Total slots","Available","Occupied","Cars  /  Bikes"};for(int i=0;i<4;i++){JPanel tile=new JPanel(new GridLayout(2,1,0,6));tile.setBackground(Color.WHITE);tile.setBorder(new EmptyBorder(14,18,14,18));JLabel n=new JLabel("0");n.setFont(new Font("Segoe UI",Font.BOLD,25));n.setForeground(UiStyle.BLUE);JLabel l=new JLabel(labels[i]);l.setForeground(UiStyle.MUTED);tile.add(n);tile.add(l);stats[i]=n;statsPanel.add(tile);}JPanel parking=new JPanel(new BorderLayout(0,10));parking.setBackground(Color.WHITE);parking.setBorder(new EmptyBorder(16,18,18,18));JLabel title=new JLabel("Parking area  •  click a slot for details");title.setFont(UiStyle.BOLD);slotsPanel.setOpaque(false);parking.add(title,BorderLayout.NORTH);parking.add(new JScrollPane(slotsPanel),BorderLayout.CENTER);body.add(statsPanel,BorderLayout.NORTH);body.add(parking,BorderLayout.CENTER);p.add(body,BorderLayout.CENTER);p.add(status,BorderLayout.SOUTH);return p;}
    private JPanel entryPage(){JPanel p=basePage("Vehicle entry","Register a car or bike and assign its first available slot");JPanel box=whiteCard();box.setLayout(new GridBagLayout());GridBagConstraints c=constraints();field(box,c,0,"Registration number",registration);field(box,c,2,"Vehicle type",vehicleType);field(box,c,4,"Owner name (optional)",owner);JButton submit=primary("Register vehicle");c.gridx=1;c.gridy=6;c.anchor=GridBagConstraints.WEST;box.add(submit,c);submit.addActionListener(e->registerVehicle());JPanel wrap=new JPanel(new BorderLayout());wrap.setOpaque(false);wrap.add(box,BorderLayout.NORTH);p.add(wrap,BorderLayout.CENTER);return p;}
    private JPanel exitPage(){JPanel p=basePage("Vehicle exit & billing","Find the active ticket, review charges, and confirm the exit");JPanel box=whiteCard();box.setLayout(new GridBagLayout());GridBagConstraints c=constraints();field(box,c,0,"Vehicle registration or ticket ID",lookup);JButton search=primary("Calculate bill");c.gridx=1;c.gridy=2;c.anchor=GridBagConstraints.WEST;box.add(search,c);JTextArea summary=new JTextArea(8,48);summary.setEditable(false);summary.setLineWrap(true);summary.setWrapStyleWord(true);summary.setFont(UiStyle.REGULAR);summary.setText(exitSummary.getText());c.gridx=0;c.gridy=3;c.gridwidth=2;c.fill=GridBagConstraints.HORIZONTAL;box.add(new JScrollPane(summary),c);JButton confirm=primary("Confirm payment & exit");c.gridy=4;c.fill=GridBagConstraints.NONE;box.add(confirm,c);search.addActionListener(e->{try{pendingExit=manager.findActive(lookup.getText());LocalDateTime now=LocalDateTime.now();Duration d=pendingExit.getDuration(now);summary.setText("Ticket: "+pendingExit.getTicketId()+"\nVehicle: "+pendingExit.getRegistrationNumber()+" ("+pendingExit.getVehicleType()+")\nSlot: "+pendingExit.getSlotId()+"\nEntry: "+pendingExit.getEntryTime().format(DATE)+"\nExit estimate: "+now.format(DATE)+"\nDuration: "+duration(d)+"\nRate: ₹"+pendingExit.getVehicleType().hourlyRate()+" / started hour\nAmount payable: ₹"+manager.previewCharge(pendingExit,now));}catch(VehicleNotFoundException ex){pendingExit=null;showError(ex.getMessage());}});confirm.addActionListener(e->{if(pendingExit==null){showError("Calculate a bill before confirming exit.");return;}int answer=JOptionPane.showConfirmDialog(this,"Confirm payment and release slot "+pendingExit.getSlotId()+"?","Confirm vehicle exit",JOptionPane.YES_NO_OPTION);if(answer==JOptionPane.YES_OPTION){try{ParkingRecord done=manager.completeExit(pendingExit.getTicketId());scheduleSave();pendingExit=null;summary.setText("Exit complete. ₹"+done.getAmountPaid()+" recorded for "+done.getRegistrationNumber()+".");refreshAll();}catch(VehicleNotFoundException ex){showError(ex.getMessage());}}});JPanel wrap=new JPanel(new BorderLayout());wrap.setOpaque(false);wrap.add(box,BorderLayout.NORTH);p.add(wrap,BorderLayout.CENTER);return p;}
    private JPanel historyPage(){JPanel p=basePage("Parking history","Completed parking transactions stored on this computer");JPanel body=new JPanel(new BorderLayout(0,12));body.setOpaque(false);JPanel filters=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));filters.setOpaque(false);historySearch.setPreferredSize(new Dimension(220,34));filters.add(new JLabel("Vehicle number"));filters.add(historySearch);filters.add(historyType);JButton search=primary("Search");filters.add(search);JButton clear=new JButton("Clear");filters.add(clear);search.addActionListener(e->refreshHistory());clear.addActionListener(e->{historySearch.setText("");historyType.setSelectedIndex(0);refreshHistory();});historyTable.setRowHeight(28);historyTable.setFillsViewportHeight(true);body.add(filters,BorderLayout.NORTH);body.add(new JScrollPane(historyTable),BorderLayout.CENTER);p.add(body,BorderLayout.CENTER);return p;}
    private JPanel whiteCard(){JPanel panel=new JPanel();panel.setBackground(Color.WHITE);panel.setBorder(new EmptyBorder(24,26,24,26));return panel;}
    private GridBagConstraints constraints(){GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(8,8,8,8);c.anchor=GridBagConstraints.WEST;c.fill=GridBagConstraints.HORIZONTAL;c.weightx=1;return c;}
    private void field(JPanel p,GridBagConstraints c,int row,String label,JComponent input){c.gridx=0;c.gridy=row;c.gridwidth=2;p.add(new JLabel(label),c);LoginFrame.styleField(input);c.gridy=row+1;p.add(input,c);c.gridwidth=1;}
    private JButton primary(String text){JButton b=new JButton(text);b.setBackground(UiStyle.BLUE);b.setForeground(Color.WHITE);b.setFont(UiStyle.BOLD);b.setFocusPainted(false);return b;}
    private void registerVehicle(){if(!dataReady){showError("Saved parking data is still loading. Please try again in a moment.");return;}try{ParkingRecord r=manager.parkVehicle(registration.getText(),(VehicleType)vehicleType.getSelectedItem(),owner.getText());scheduleSave();JOptionPane.showMessageDialog(this,"Ticket: "+r.getTicketId()+"\nVehicle: "+r.getRegistrationNumber()+" ("+r.getVehicleType()+")\nSlot: "+r.getSlotId()+"\nEntry: "+r.getEntryTime().format(DATE),"Vehicle parked",JOptionPane.INFORMATION_MESSAGE);registration.setText("");owner.setText("");refreshAll();cards.show(content,"Dashboard");}catch(InvalidVehicleException|DuplicateVehicleException|SlotUnavailableException ex){showError(ex.getMessage());}}
    private void scheduleSave(){fileWorker.submit(()->{try{manager.save();SwingUtilities.invokeLater(()->status.setText("Saved locally • "+LocalDateTime.now().format(DateTimeFormatter.ofPattern("HH:mm:ss"))));}catch(Exception ex){SwingUtilities.invokeLater(()->JOptionPane.showMessageDialog(this,"Could not save parking data: "+ex.getMessage(),"Storage error",JOptionPane.ERROR_MESSAGE));}});}
    private void refreshAll(){refreshStats();refreshSlots();refreshHistory();}
    private void refreshStats(){int occupied=manager.getOccupiedCount(),cars=manager.getOccupiedCount(VehicleType.CAR),bikes=manager.getOccupiedCount(VehicleType.BIKE);stats[0].setText(String.valueOf(ParkingManager.CAPACITY));stats[1].setText(String.valueOf(ParkingManager.CAPACITY-occupied));stats[2].setText(String.valueOf(occupied));stats[3].setText(cars+" / "+bikes);}
    private void refreshSlots(){slotsPanel.removeAll();for(ParkingSlot slot:manager.getSlots()){boolean occupied=slot.getStatus()==ParkingStatus.OCCUPIED;JPanel card=new JPanel(new GridLayout(2,1,0,3));card.setBackground(occupied?UiStyle.RED:UiStyle.GREEN);card.setBorder(new EmptyBorder(10,10,10,10));JLabel id=new JLabel(slot.getId());id.setFont(UiStyle.BOLD);id.setForeground(occupied?UiStyle.RED_TEXT:UiStyle.GREEN_TEXT);JLabel state=new JLabel(slot.getType()+" • "+(occupied?"Occupied":"Available"));state.setFont(new Font("Segoe UI",Font.PLAIN,11));card.add(id);card.add(state);card.addMouseListener(new MouseAdapter(){@Override public void mouseClicked(MouseEvent e){String info="Slot "+slot.getId()+" — "+slot.getType()+" — "+slot.getStatus();if(occupied){for(ParkingRecord r:manager.getActiveRecords())if(r.getSlotId().equals(slot.getId()))info+="\nVehicle: "+r.getRegistrationNumber()+"\nTicket: "+r.getTicketId();}JOptionPane.showMessageDialog(DashboardFrame.this,info,"Parking slot",JOptionPane.INFORMATION_MESSAGE);}});slotsPanel.add(card);}slotsPanel.revalidate();slotsPanel.repaint();}
    private void refreshHistory(){tableModel.setRowCount(0);Object selected=historyType.getSelectedItem();VehicleType type=selected instanceof VehicleType?(VehicleType)selected:null;List<ParkingRecord> records=manager.searchHistory(historySearch.getText(),type);for(ParkingRecord r:records){Duration d=r.getDuration(r.getExitTime());tableModel.addRow(new Object[]{r.getTicketId(),r.getRegistrationNumber(),r.getVehicleType(),r.getSlotId(),r.getEntryTime().format(DATE),r.getExitTime().format(DATE),duration(d),"₹"+r.getAmountPaid()});}}
    private String duration(Duration d){long mins=d.toMinutes();return (mins/60)+"h "+(mins%60)+"m";}
    private void showError(String message){JOptionPane.showMessageDialog(this,message,"Parking",JOptionPane.WARNING_MESSAGE);}
}
